CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE TYPE public.account_role_enum AS ENUM('owner','admin','agent','viewer');
CREATE TABLE accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text,owner_user_id uuid,created_at timestamptz DEFAULT now());
CREATE TABLE profiles(user_id uuid PRIMARY KEY,account_id uuid REFERENCES accounts(id),account_role account_role_enum,full_name text,email text);
CREATE TABLE account_members(account_id uuid REFERENCES accounts(id),user_id uuid,role account_role_enum,joined_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),PRIMARY KEY(account_id,user_id));
CREATE UNIQUE INDEX one_owner ON account_members(account_id) WHERE role='owner';
CREATE FUNCTION is_account_member(target_account_id uuid,min_role account_role_enum DEFAULT 'viewer') RETURNS boolean LANGUAGE sql SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM account_members WHERE account_id=target_account_id AND user_id=auth.uid() AND CASE min_role WHEN 'owner' THEN role='owner' WHEN 'admin' THEN role IN ('owner','admin') WHEN 'agent' THEN role IN ('owner','admin','agent') ELSE true END) $$;
CREATE TABLE ai_configs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text);
CREATE TABLE ai_usage_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text);
CREATE TABLE ai_knowledge_chunks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid,content text,fts tsvector GENERATED ALWAYS AS(to_tsvector('simple',content)) STORED);
CREATE TABLE conversations(id uuid PRIMARY KEY,ai_reply_count integer DEFAULT 0,ai_autoreply_disabled boolean DEFAULT false,assigned_agent_id uuid);
CREATE TABLE flows(id uuid PRIMARY KEY,account_id uuid);
CREATE TABLE flow_nodes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),flow_id uuid,node_key text,node_type text,config jsonb,position_x integer,position_y integer);
CREATE TABLE flow_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),flow_id uuid,status text,current_node_key text,ended_at timestamptz,end_reason text);
CREATE TABLE quick_replies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text,content_text text,interactive_payload jsonb);
CREATE TABLE broadcasts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid,user_id uuid,name text,template_name text,template_language text,status text,total_recipients integer);
CREATE TABLE broadcast_recipients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),broadcast_id uuid,contact_id uuid,status text,template_params jsonb);
CREATE TABLE automation_pending_executions(id uuid PRIMARY KEY DEFAULT gen_random_uuid());
GRANT USAGE ON SCHEMA auth,public TO anon,authenticated,service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated,service_role;
COMMENT ON DATABASE rz_upstream_integrity_test IS 'RZ isolated upstream migration test';
